using UnityEngine;

namespace TLC.SpriteAnimation
{
    /// <summary>
    /// One animation clip: the frames of a single sprite sheet, plus how fast to play them.
    ///
    /// Deliberately one asset per sheet, so the artist's deliverable and the data have a 1:1
    /// relationship and the whole thing can be regenerated by a tool rather than hand-wired.
    ///
    /// Keep these OUT of any registry asset that lives in a Resources folder. Unity resolves an
    /// asset's entire reference graph on load, so frames hung off an always-loaded registry make
    /// every frame of every character resident as soon as anything touches it. A registry is a
    /// small lookup; frames are bulk payload, and the two want opposite loading behaviour.
    /// </summary>
    [CreateAssetMenu(fileName = "SpriteAnimation", menuName = "TLC/Sprite Animation")]
    public class SpriteAnimationSO : ScriptableObject
    {
        [Tooltip("Frames in play order. Frame 0 doubles as the rest pose between plays, so it " +
                 "should be the character's neutral drawing.")]
        public Sprite[] frames;

        [Tooltip("Playback rate. 24 is a reasonable default for a 25-frame loop — about one " +
                 "second per play. This is the only speed control; there is deliberately no " +
                 "second multiplier elsewhere.")]
        [Range(1f, 60f)]
        public float framesPerSecond = 24f;

        [Header("Scheduling")]
        [Tooltip("Loop forever with no pauses. Leave off for a burst that plays, rests, replays.")]
        public bool playContinuously;

        [Tooltip("Play once and HOLD, never replaying. For poses that settle and stay — a " +
                 "look-at turns the head and keeps looking. Overrides the rest interval, which " +
                 "only makes sense for something that returns to neutral.")]
        public bool holdLastFrame;

        [Tooltip("Which frame to stop on and hold, 0-based. -1 means the last frame.\n\n" +
                 "Set this when the sheet animates out AND BACK — if the final frame returns to " +
                 "neutral, holding it looks identical to idle and the pose reads as never having " +
                 "happened. Point it at the frame where the pose is fullest; playback stops " +
                 "there rather than running on to the end.")]
        public int holdFrameIndex = -1;

        /// <summary>
        /// Resolved hold frame: the authored index, clamped, or the last frame when unset.
        /// </summary>
        public int HoldFrame
        {
            get
            {
                if (!IsValid) return 0;
                if (holdFrameIndex < 0) return frames.Length - 1;
                return Mathf.Clamp(holdFrameIndex, 0, frames.Length - 1);
            }
        }

        [Tooltip("Speed multiplier while this pose is being reversed back to neutral so another " +
                 "direction can take over. Higher is snappier; a head turn should feel like a " +
                 "reaction, not a performance.")]
        [Range(0.5f, 8f)]
        public float transitionSpeedMultiplier = 3f;

        [Tooltip("Seconds of rest between plays, as (min, max). Rolled fresh after every play so " +
                 "two characters on screen drift apart instead of blinking in lockstep. " +
                 "Ignored when Play Continuously is on.\n\n" +
                 "Lives here rather than on the animator because scheduling belongs to the clip: " +
                 "an idle wants a long rest, a triggered reaction wants none.")]
        public Vector2 restBetweenPlays = new Vector2(4f, 8f);

        [Tooltip("Extra scale applied on top of matching the static sprite's frame size, to " +
                 "correct for the sheet padding differently from the static art. Baked by the " +
                 "sheet importer from the actual opaque pixel bounds; 1 means no correction.")]
        [Range(0.1f, 8f)]
        public float artFitMultiplier = 1f;

        public bool IsValid => frames != null && frames.Length > 0;

        public int FrameCount => frames != null ? frames.Length : 0;

        /// <summary>Seconds one full play takes.</summary>
        public float Duration => framesPerSecond > 0.001f ? FrameCount / framesPerSecond : 0f;

        /// <summary>
        /// The pose held between plays: the last frame for a hold-style clip, otherwise the
        /// first. A look-at that fell back to frame 0 would snap its head forward again the
        /// instant it finished turning.
        /// </summary>
        public Sprite RestFrame =>
            !IsValid ? null : frames[holdLastFrame ? HoldFrame : 0];

        /// <summary>The frame a clip starts from, always the first.</summary>
        public Sprite FirstFrame => IsValid ? frames[0] : null;
    }
}
